selector_to_html = {"a[href=\"#gweithredyddion-rhifyddol\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">1.1. </span>Gweithredyddion Rhifyddol<a class=\"headerlink\" href=\"#gweithredyddion-rhifyddol\" title=\"Link to this heading\">#</a></h2><p>Mae <strong><a class=\"reference internal\" href=\"../glossary.html#term-gweithredydd-rhifyddol\"><span class=\"xref std std-term\">gweithredydd rhifyddol</span></a></strong> yn symbol sy\u2019n cynrychioli cyfrifiant\nrhifyddol. Er enghraifft, mae\u2019r arwydd adio, <code class=\"docutils literal notranslate\"><span class=\"pre\">+</span></code>, yn perfformio adio.</p>", "a[href=\"#gofyn-i-gynorthwyydd-rhithwir\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">1.9.1. </span>Gofyn i gynorthwyydd rhithwir<a class=\"headerlink\" href=\"#gofyn-i-gynorthwyydd-rhithwir\" title=\"Link to this heading\">#</a></h3><p>Wrth i chi weithio drwy\u2019r llyfr hwn, mae sawl ffordd y gallwch ddefnyddio\ncynorthwyydd rhithwir neu sgwrsfot i\u2019ch helpu i ddysgu.</p>", "a[href=\"../glossary.html#term-mynegiad\"]": "<dt id=\"term-mynegiad\">mynegiad</dt><dd><p>expression</p></dd>", "a[href=\"#mynegiadau\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">1.2. </span>Mynegiadau<a class=\"headerlink\" href=\"#mynegiadau\" title=\"Link to this heading\">#</a></h2><p>Gelwir casgliad o weithredyddion a rhifau yn <strong><a class=\"reference internal\" href=\"../glossary.html#term-mynegiad\"><span class=\"xref std std-term\">mynegiad</span></a></strong>. Gall mynegiad\ngynnwys unrhyw nifer o weithredyddion a rhifau. Er enghraifft, dyma fynegiad sy\u2019n\ncynnwys dau weithredydd.</p>", "a[href=\"../glossary.html#term-gwerth\"]": "<dt id=\"term-gwerth\">gwerth</dt><dd><p>value</p></dd>", "a[href=\"#dadnamu\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">1.7. </span>Dadnamu<a class=\"headerlink\" href=\"#dadnamu\" title=\"Link to this heading\">#</a></h2><p>Mae rhaglenwyr yn gwneud camgymeriadau. Am resymau mympwyol, gelwir gwallau rhaglennu\nyn **<a class=\"reference internal\" href=\"../glossary.html#term-nam\"><span class=\"xref std std-term\">nam</span></a>**au a gelwir y broses o\u2019u holrhain yn <strong><a class=\"reference internal\" href=\"../glossary.html#term-dadnamu\"><span class=\"xref std std-term\">dadnamu</span></a></strong>.</p><p>Mae rhaglennu, ac yn enwedig dadnamu, weithiau\u2019n codi teimladau cryf. Os ydych yn cael\ntrafferth gyda nam anodd, efallai y byddwch yn teimlo\u2019n ddig, yn drist, neu\u2019n\nchwithig.</p>", "a[href=\"../glossary.html#term-gweithredydd\"]": "<dt id=\"term-gweithredydd\">gweithredydd</dt><dd><p>operator</p></dd>", "a[href=\"#ymarferion\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">1.9. </span>Ymarferion<a class=\"headerlink\" href=\"#ymarferion\" title=\"Link to this heading\">#</a></h2><h3><span class=\"section-number\">1.9.1. </span>Gofyn i gynorthwyydd rhithwir<a class=\"headerlink\" href=\"#gofyn-i-gynorthwyydd-rhithwir\" title=\"Link to this heading\">#</a></h3><p>Wrth i chi weithio drwy\u2019r llyfr hwn, mae sawl ffordd y gallwch ddefnyddio\ncynorthwyydd rhithwir neu sgwrsfot i\u2019ch helpu i ddysgu.</p>", "a[href=\"#rhaglennu-fel-ffordd-o-feddwl\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">1. </span>Rhaglennu fel ffordd o feddwl<a class=\"headerlink\" href=\"#rhaglennu-fel-ffordd-o-feddwl\" title=\"Link to this heading\">#</a></h1><p>Nod cyntaf y llyfr hwn yw eich dysgu sut i raglennu yn Python.\nOnd mae dysgu rhaglennu yn golygu dysgu ffordd newydd o feddwl, felly ail nod y llyfr\nhwn yw eich helpu i feddwl fel gwyddonydd cyfrifiadurol.\nMae\u2019r ffordd hon o feddwl yn cyfuno rhai o nodweddion gorau mathemateg, peirianneg, a\ngwyddoniaeth naturiol.\nFel mathemategwyr, mae gwyddonwyr cyfrifiadurol yn defnyddio <a class=\"reference internal\" href=\"../glossary.html#term-iaith-ffurfiol\"><span class=\"xref std std-term\">iaith ffurfiol</span></a>au i\nddynodi syniadau \u2014 cyfrifiannau yn benodol.\nFel peirianwyr, maen nhw\u2019n dylunio pethau, yn cydosod cydrannau i systemau ac yn\ngwerthuso cyfaddawdau ymhlith dewisiadau amgen.\nFel gwyddonwyr, maen nhw\u2019n arsylwi ymddygiad systemau cymhleth, yn llunio\ndamcaniaethau, ac yn profi rhagfynegiadau.</p><p>Byddwn yn dechrau gydag elfennau mwyaf sylfaenol rhaglennu ac yn symud ymlaen oddi\nyno. Yn y bennod hon, byddwn yn gweld sut mae Python yn cynrychioli rhifau,\nllythrennau, a geiriau. A byddwch yn dysgu sut i berfformio gweithrediadau rhifyddol.</p>", "a[href=\"../glossary.html#term-dadnamu\"]": "<dt id=\"term-dadnamu\">dadnamu</dt><dd><p>debugging / debug</p></dd>", "a[href=\"../glossary.html#term-iaith-naturiol\"]": "<dt id=\"term-iaith-naturiol\">iaith naturiol</dt><dd><p>natural language</p></dd>", "a[href=\"#llinynnau\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">1.4. </span>Llinynnau<a class=\"headerlink\" href=\"#llinynnau\" title=\"Link to this heading\">#</a></h2><p>Yn ogystal \u00e2 rhifau, gall Python hefyd gynrychioli dilyniannau o lythrennau, a elwir\nyn **<a class=\"reference internal\" href=\"../glossary.html#term-llinyn\"><span class=\"xref std std-term\">llinyn</span></a>**nau am fod y llythrennau wedi\u2019u llinynnu gyda\u2019i gilydd fel\ngleiniau ar gadwyn. I ysgrifennu llinyn, gallwn roi dilyniant o lythrennau y tu mewn i\nddyfynodau syth.</p>", "a[href=\"../glossary.html#term-nam\"]": "<dt id=\"term-nam\">nam</dt><dd><p>bug</p></dd>", "a[href=\"../glossary.html#term-iaith-ffurfiol\"]": "<dt id=\"term-iaith-ffurfiol\">iaith ffurfiol</dt><dd><p>formal language</p></dd>", "a[href=\"../glossary.html#term-galwad-swyddogaeth\"]": "<dt id=\"term-galwad-swyddogaeth\">galwad swyddogaeth</dt><dd><p>function call</p></dd>", "a[href=\"../glossary.html#term-llinyn\"]": "<dt id=\"term-llinyn\">llinyn</dt><dd><p>string</p></dd>", "a[href=\"../glossary.html#term-swyddogaeth\"]": "<dt id=\"term-swyddogaeth\">swyddogaeth</dt><dd><p>function (programming)</p></dd>", "a[href=\"#id3\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">1.9.5. </span>Ymarfer<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h3><p>Mae\u2019r cwestiynau canlynol yn rhoi cyfle i chi ymarfer ysgrifennu mynegiadau\nrhifyddol.</p>", "a[href=\"../glossary.html#term-gwall-cystrawen\"]": "<dt id=\"term-gwall-cystrawen\">gwall cystrawen</dt><dd><p>syntax error</p></dd>", "a[href=\"#id1\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">1.9.3. </span>Ymarfer<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h3><p>Pan fyddwch yn dysgu am nodwedd newydd, dylech roi cynnig arni a gwneud camgymeriadau\u2019n\nfwriadol. Fel hyn, byddwch yn dysgu\u2019r negeseuon gwall, a phan welwch nhw eto, byddwch\nyn gwybod beth maen nhw\u2019n ei olygu. Mae\u2019n well gwneud camgymeriadau nawr ac yn\nfwriadol na wedyn ac yn ddamweiniol.</p>", "a[href=\"../glossary.html#term-math\"]": "<dt id=\"term-math\">math</dt><dd><p>type (kind of value)</p></dd>", "a[href=\"../glossary.html#term-cydgatenu\"]": "<dt id=\"term-cydgatenu\">cydgatenu</dt><dd><p>concatenation</p></dd>", "a[href=\"#ymarfer\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">1.9.2. </span>Ymarfer<a class=\"headerlink\" href=\"#ymarfer\" title=\"Link to this heading\">#</a></h3><p>Efallai eich bod yn meddwl tybed beth mae <code class=\"docutils literal notranslate\"><span class=\"pre\">round</span></code> yn ei wneud os yw rhif yn gorffen\nmewn <code class=\"docutils literal notranslate\"><span class=\"pre\">0.5</span></code>. Yr ateb yw ei fod weithiau\u2019n talgrynnu i fyny ac weithiau i lawr. Rhowch\ngynnig ar yr enghreifftiau hyn a gweld a allwch ddarganfod pa reol y mae\u2019n ei dilyn.</p>", "a[href=\"../glossary.html#term-gweithredydd-rhifyddol\"]": "<dt id=\"term-gweithredydd-rhifyddol\">gweithredydd rhifyddol</dt><dd><p>arithmetic operator</p></dd>", "a[href=\"../glossary.html#term-cyfanrif\"]": "<dt id=\"term-cyfanrif\">cyfanrif</dt><dd><p>integer</p></dd>", "a[href=\"#rhestr-termau-r-bennod\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">1.8. </span>Rhestr Termau\u2019r Bennod<a class=\"headerlink\" href=\"#rhestr-termau-r-bennod\" title=\"Link to this heading\">#</a></h2><p><strong>gweithredydd rhifyddol:</strong>\nSymbol, fel <code class=\"docutils literal notranslate\"><span class=\"pre\">+</span></code> a <code class=\"docutils literal notranslate\"><span class=\"pre\">*</span></code>, sy\u2019n dynodi gweithrediad rhifyddol fel adio neu luosi.</p><p><strong>cyfanrif:</strong>\nMath sy\u2019n cynrychioli rhifau heb ran ffracsiynol na degol.</p>", "a[href=\"#gwerthoedd-a-mathau\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">1.5. </span>Gwerthoedd a Mathau<a class=\"headerlink\" href=\"#gwerthoedd-a-mathau\" title=\"Link to this heading\">#</a></h2><p>Hyd yn hyn rydym wedi gweld tri math o werth:</p>", "a[href=\"#id2\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">1.9.4. </span>Ymarfer<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h3><p>Cofiwch fod gan bob mynegiad werth, bod gan bob gwerth fath, a gallwn ddefnyddio\u2019r\nswyddogaeth <code class=\"docutils literal notranslate\"><span class=\"pre\">type</span></code> i ddarganfod math unrhyw werth.</p><p>Beth yw math gwerth y mynegiadau canlynol? Gwnewch eich dyfaliad gorau ar gyfer pob\nun, ac yna defnyddiwch <code class=\"docutils literal notranslate\"><span class=\"pre\">type</span></code> i ddarganfod.</p>", "a[href=\"#swyddogaethau-rhifyddol\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">1.3. </span>Swyddogaethau Rhifyddol<a class=\"headerlink\" href=\"#swyddogaethau-rhifyddol\" title=\"Link to this heading\">#</a></h2><p>Yn ogystal \u00e2\u2019r gweithredyddion rhifyddol, mae Python yn darparu ychydig o\n**<a class=\"reference internal\" href=\"../glossary.html#term-swyddogaeth\"><span class=\"xref std std-term\">swyddogaeth</span></a>**au sy\u2019n gweithio gyda rhifau. Er enghraifft, mae\u2019r swyddogaeth\n<code class=\"docutils literal notranslate\"><span class=\"pre\">round</span></code> yn cymryd rhif pwynt arnawf ac yn ei dalgrynnu i\u2019r cyfanrif agosaf.</p>", "a[href=\"../glossary.html#term-real\"]": "<dt id=\"term-real\">real</dt><dd><p>float / real number</p></dd>", "a[href=\"../glossary.html#term-gweithredyn\"]": "<dt id=\"term-gweithredyn\">gweithredyn</dt><dd><p>operand</p></dd>", "a[href=\"#ieithoedd-ffurfiol-a-naturiol\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">1.6. </span>Ieithoedd Ffurfiol a Naturiol<a class=\"headerlink\" href=\"#ieithoedd-ffurfiol-a-naturiol\" title=\"Link to this heading\">#</a></h2><p>**<a class=\"reference internal\" href=\"../glossary.html#term-iaith-naturiol\"><span class=\"xref std std-term\">iaith naturiol</span></a>**au yw\u2019r ieithoedd y mae pobl yn eu siarad, fel Saesneg,\nSbaeneg, a Ffrangeg. Ni chawsant eu dylunio gan bobl; fe wnaethant esblygu\u2019n naturiol.</p><p>Mae **<a class=\"reference internal\" href=\"../glossary.html#term-iaith-ffurfiol\"><span class=\"xref std std-term\">iaith ffurfiol</span></a>**au yn ieithoedd a ddyluniwyd gan bobl ar gyfer\ncymwysiadau penodol. Er enghraifft, mae\u2019r nodiant a ddefnyddir gan fathemategwyr yn\niaith ffurfiol sy\u2019n arbennig o dda am ddynodi perthnasoedd rhwng rhifau a symbolau. Yn\nyr un modd, mae ieithoedd rhaglennu yn ieithoedd ffurfiol sydd wedi\u2019u dylunio i fynegi\ncyfrifiannau.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
